import { useStompClient, useSubscription } from 'react-stomp-hooks';
import SockJsClient from 'react-stomp';
import { Client } from '@stomp/stompjs';
import user_icon from '../img/user_icon.png'
import { Flex } from 'antd';
// import { messages } from 'react-stomp-hooks/dist/mock/client';


const  Home = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const log = location.state?.from?.pathname || "/logout";
    let currentUser = 'Jon-Thomas2';
    let email = 'jt010051@gmail.com';
    let phone = ''
    const [thisMessage, setThisMessage] = useState('')
  const[name, setName] = useState('')
    const [activeUser, setActiveUser] = useState(false);
    const [listOfUsers, setListOfUsers] = useState([])
	const [selectedUser, setSelectedUser] = useState('')
    const [recievedMessages, setRecievedMessages] = useState(false)
const [newMessages, setNewMessages] = useState(false)
const[myMessage, setMyMessage] = useState("")
const[message, setMessage] = useState('')
const [isNewMessage, setIsNewMessage] = useState(false)
const[idArr, setIdArr] = useState([])
const[firstRun, setFirstRun] = useState(true)
const [userChatResponse, setUserChatResponse] = useState({});
// const [currentData, setCurrentData] = useState({});

     const findAndDisplayConnectedUsers = async(e) =>{

        try{
        const connectedUsersList  = await axios.get('chatUsers/allUsers');
        setListOfUsers(connectedUsersList.data

            .filter( user => user.email !== email)
            .filter( user => user.phone !== phone)

            .map(user => user.firstName))
        }
        catch (err) {
            console.log(err);

        }

    }
const   fetchAndDisplayUserChat = async()=>{    
const response = await axios.get(`/messages/${currentUser}/${selectedUser}`)

if(response.data){
    setUserChatResponse(response.data)
}


    }


    const stompClient = useStompClient();
	useSubscription(`/user/public`)
	useSubscription(`/user/${currentUser}/queue/messages`, (message2) => {

        console.log(message2.body);

       let newMessage = message2.body.split("\"content\":")[1];
    let nextString = newMessage.split("}")[0]
       let finalStr = nextString.replaceAll("\"", "");
       setMessage(finalStr)
        let newObj ={
            id : userChatResponse.length,
            chatId : 'Jon-Thomas_Jon-Thomas2',
            content : finalStr,
            senderId : selectedUser,
            recipientId : currentUser,
            timeStamp : new Date
        }
console.log(newObj);


    let data = {}
    if(userChatResponse) 
     data = userChatResponse
    data.push(newObj)
console.log(data);

       setUserChatResponse(data)

        setRecievedMessages(true)


    }

 )
 useSubscription("/user/queue/reply", (message) => setMyMessage(message.body));



  if(stompClient){
    stompClient.publish("/app/user.addUser",
        {},
        JSON.stringify({firstName: currentUser, status:'ONLINE'})
        )

  }



    const publishMessage = (e) => {

        if(stompClient) {
            const chatMessage = {
                senderId: currentUser,
                recipientId: selectedUser,
                content: thisMessage,
                timeStamp: new Date() 
            }
          stompClient.publish({destination: '/app/chat', body: JSON.stringify(chatMessage)})
        //   displayMessage(currentUser, thisMessage)
        // stompClient.publish({destination: '/app/user-message', body: JSON.stringify(chatMessage.content)})




    let data = {}
    if(userChatResponse) 
     data = userChatResponse
    data.push(chatMessage)

       setUserChatResponse(data)

        setRecievedMessages(true)





        document.getElementById("message").value = '';

        setNewMessages(true)

        }
      }
if (!currentUser) {
    currentUser = localStorage.getItem("phone");
}


const userDetailsApi = `user/userDetails/${currentUser}`



const logout =()=>{
    navigate(log, { replace: true });

}

useEffect(()=>{
findAndDisplayConnectedUsers()

},[])
useEffect(()=>{
if(activeUser){
    fetchAndDisplayUserChat()
}
},[selectedUser])

const recievedMessgs = () =>{

if(Object.keys(userChatResponse).length !== 0  
) return(
    userChatResponse.map((data)=>{


                return(
<div className={['message', data.senderId === currentUser 
  ? 'sender' : 'receiver'].join(" ")}>
<p>
{ data.content }


</p>
</div>
                )          
            })
)
}

// useEffect(()=>{
//   if(newMessages)  fetchAndDisplayUserChat()




//     setNewMessages(false)
// },[newMessages])

useEffect(() => {
    const listener = event => {
      if (event.code === "Enter" || event.code === "NumpadEnter") {
        console.log("Enter key was pressed. Run your function.");
        event.preventDefault();
        publishMessage()
      }
    };
    document.addEventListener("keydown", listener);
    return () => {
      document.removeEventListener("keydown", listener);
    };
  }, []);





    return (

      <>
   <div onClick={() =>{
    if(selectedUser) setSelectedUser('')
    if(activeUser) setActiveUser(false)
   }}>
      <h2>Hello {currentUser}</h2>
      </div>
<div className="chat-container" id="chat-page">
    <div className="users-list">
        <div className="users-list-container">
            <h2>Online Users</h2>
            <ul id="connectedUsers" > 
            </ul>
        </div>
        <div>

            <p id="connected-user-fullname"></p>
       {listOfUsers
            .map(user => {
                return   (
                <ul>
                <li className={['user-item', user === selectedUser ? 'active':null].join(" ")} 
            onClick={(e)=>{

                setActiveUser(true)
           if(user !== selectedUser) setSelectedUser(user)
            else {
                setSelectedUser('')
                setActiveUser(false)
            }
            }}><img src={user_icon} alt = {user} style={{width:20, height: 20}} />
            <span>
            {user}
            </span>
           {recievedMessages ?
             <span className='nbr-msg'>

         </span> : null
           }
 </li>
 </ul>
                )
            }
            )}


        </div>
    </div>

    <div className="chat-area">
        <div className="chat-area" id="chat-messages">         
{activeUser  ?
recievedMessgs()
: null
}    

{/* <div>The message from websocket broker for myself is {myMessage}</div> */}

{/* {message ? message : null} */}
{/* {setMessage('')} */}
        </div>
         {activeUser ? 
         <>
<form id="messageForm" name="messageForm" >
<div className="message-input">
<input autoComplete="off" type="text" id="message" placeholder="Type your message..."
        onChange={(e) => setThisMessage(e.target.value)}  />
        <Button onClick={(e)=>{
            publishMessage()
            setThisMessage('')

        }}>Send</Button>

            </div>
         </form>

         </>
         : null}
  </div>
</div>
   <script src="https://cdnjs.cloudflare.com/ajax/libs/sockjs-client/1.1.4/sockjs.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/stomp.js/2.3.3/stomp.min.js"></script>   
<Button  onClick={logout}>Logout</Button>

      </>
    );
}

export default Home;
